#include <iostream>
#include <sstream>

int total(int aceptados, int rechazados) {
    return aceptados + rechazados;
}

void escribir_total(std::ostream& destino, int cantidad) {
    destino << "Total=" << cantidad;
}

int main() {
    int cantidad = total(6, 2);
    std::ostringstream memoria;
    escribir_total(memoria, cantidad);
    std::cout << memoria.str();
    return 0;
}

