#include <iostream>
#include <sstream>

bool leer_entero(std::istream& origen, int& destino) {
    int candidato{0};
    if (!(origen >> candidato)) { return false; }
    destino = candidato;
    return true;
}

int main() {
    std::istringstream memoria{"x"};
    int cantidad{4};
    bool leido = leer_entero(memoria, cantidad);
    std::cout << leido << ":" << cantidad;
    return 0;
}

