#include <iostream>
#include <sstream>

bool leer_par(std::istream& origen, int& aceptados, int& rechazados) {
    int nuevo_aceptados{0};
    int nuevo_rechazados{0};
    if (!(origen >> nuevo_aceptados >> nuevo_rechazados)) {
        return false;
    }
    aceptados = nuevo_aceptados;
    rechazados = nuevo_rechazados;
    return true;
}

int balance(int aceptados, int rechazados) {
    return aceptados - rechazados;
}

void escribir_balance(std::ostream& destino, int valor) {
    destino << "Balance=" << valor;
}

int main() {
    std::istringstream entrada{"7 2"};
    int aceptados{9};
    int rechazados{4};
    if (!leer_par(entrada, aceptados, rechazados)) {
        std::cout << "Invalid input|" << aceptados << ":" << rechazados;
        return 1;
    }
    std::ostringstream captura;
    escribir_balance(captura, balance(aceptados, rechazados));
    std::cout << captura.str();
    return 0;
}
